namespace Mcs.Compiler;

/// <summary>
/// C# stub declarations for MC#'s built-in APIs.
/// Roslyn type-checks against these declarations, and the code generator reads
/// their attributes ([Intrinsic], [Nbt], [McAttribute], [McId], [State]) to decide which commands to emit.
/// The method bodies never run. EntityType and the per-block classes are generated by PreludeGen.
/// </summary>
public static class Prelude
{
    public const string GlobalUsings = """
        global using MCS;
        global using static MCS.Builtins;
        """;

    public const string Source = """
        namespace MCS
        {
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class IntrinsicAttribute : System.Attribute { public IntrinsicAttribute(string name) { } }

            /// Entity NBT path mapping. type: byte|short|int|long|float|double|string|int[]
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class NbtAttribute : System.Attribute { public NbtAttribute(string path, string type) { } }

            /// Entity attribute mapping (written without the "generic." prefix; the compiler adds it per version).
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class McAttributeAttribute : System.Attribute { public McAttributeAttribute(string id) { } }

            /// Minecraft ID (block / entity type / state value).
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class McIdAttribute : System.Attribute { public McIdAttribute(string id) { } }

            /// Block state property: state name and allowed values.
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class StateAttribute : System.Attribute { public StateAttribute(string name, string values) { } }

            /// Marks a class as an entity class: instances are entities of this type (+ tag).
            [System.AttributeUsage(System.AttributeTargets.Class)]
            public sealed class EntityAttribute : System.Attribute { public EntityAttribute(string type, string tag = null) { } }

            /// The member exists from this data pack format / version on (older targets are a compile error).
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class SinceAttribute : System.Attribute { public SinceAttribute(int format, string version) { } }

            /// Per-entity scoreboard field. Default objective: <namespace>.<field_name>
            [System.AttributeUsage(System.AttributeTargets.Field)]
            public sealed class ScoreAttribute : System.Attribute
            {
                public ScoreAttribute(string objective = null) { }
                public string Display { get; set; }
                public string Color { get; set; }
                public string Criteria { get; set; }
            }

            /// The method body is inlined at each call site; constant arguments stay compile-time constants.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class InlineAttribute : System.Attribute { }

            /// Runs every time the datapack loads (#minecraft:load).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class LoadAttribute : System.Attribute { }

            /// Runs every tick (#minecraft:tick).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class TickAttribute : System.Attribute { }

            // ---- Player events. The method runs as the player, at the player (@s). Parameters (all optional):
            //      a Player (that player) and, for counter events, an int (how much the counter went up).

            /// A player joins the world (every login, including the first).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnJoinAttribute : System.Attribute { }

            /// A player joins for the first time (also players online when the pack is first installed).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnFirstJoinAttribute : System.Attribute { }

            /// A player died (runs at the death position, while the player is on the death screen).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnDeathAttribute : System.Attribute { }

            /// A player respawned after dying.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnRespawnAttribute : System.Attribute { }

            /// A player killed something (mob or player). int parameter: number of kills.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnKillAttribute : System.Attribute { }

            /// A player used an item. Right-click detection works for carrot_on_a_stick and warped_fungus_on_a_stick;
            /// other items count when they are actually used (eaten, thrown, placed, …).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnRightClickAttribute : System.Attribute { public OnRightClickAttribute(string item = "carrot_on_a_stick") { } }

            /// A player ran /trigger <objective> (no operator permission needed). int parameter: the value (1 for a plain /trigger).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnTriggerAttribute : System.Attribute { public OnTriggerAttribute(string objective) { } }

            /// A player right-clicked while holding this item object (a static Item field):
            /// [OnRightClickObject(nameof(wand))]. The item must be carrot_on_a_stick or warped_fungus_on_a_stick.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnRightClickObjectAttribute : System.Attribute { public OnRightClickObjectAttribute(string field) { } }

            /// A statistic of a player went up, e.g. "minecraft.custom:minecraft.jump" or "minecraft.mined:minecraft.stone".
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnStatAttribute : System.Attribute { public OnStatAttribute(string criterion) { } }

            /// Base class of scoreboard classes: `public class test : dummy {}` — every static int/bool field
            /// is a score holder (the field name) in the class's objective (criteria dummy, created on load).
            /// Using test.anything declares the field automatically.
            public abstract class dummy { }

            /// A compile-time position (an execute context + coordinates).
            public struct Position
            {
                [Intrinsic("pos.new")] public Position(double x, double y, double z) { }
                [Intrinsic("pos.here")] public static Position Here => default;
                [Intrinsic("pos.offset")] public Position Offset(double dx, double dy, double dz) => default;
            }

            /// Base class of entity classes ([Entity("minecraft:marker", "my.tag")] class Province : EntityObject).
            public abstract class EntityObject
            {
                [Intrinsic("ent.addtag")] public void AddTag(string tag) { }
                [Intrinsic("ent.removetag")] public void RemoveTag(string tag) { }
                [Intrinsic("ent.hastag")] public bool HasTag(string tag) => false;
                [Intrinsic("ent.kill")] public void Kill() { }
                [Intrinsic("ent.merge")] public void Merge(string snbt) { }
                [Intrinsic("ent.pos")] public Position Position => default;
                [Intrinsic("ent.tp")] public void Teleport(Position pos) { }
                [Intrinsic("ent.run")] public void Run(System.Action action) { }
            }

            /// Entity queries. Selector filters use selector syntax, e.g. "tag=a,scores={x=1..}".
            public static class Entities
            {
                [Intrinsic("ents.all")] public static System.Collections.Generic.IEnumerable<T> All<T>(string filter = "", bool at = false) where T : EntityObject => null;
                [Intrinsic("ents.spawn")] public static T Spawn<T>(Position pos, string nbt = "") where T : EntityObject => null;
                [Intrinsic("ents.nearest")] public static T Nearest<T>(Position pos, double maxDistance = -1, string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.random")] public static T Random<T>(string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.first")] public static T First<T>(string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.count")] public static int Count<T>(string filter = "") where T : EntityObject => 0;
                [Intrinsic("ents.any")] public static bool Any<T>(string filter = "") where T : EntityObject => false;
                [Intrinsic("ents.self")] public static T Self<T>() where T : EntityObject => null;
                [Intrinsic("ents.uuid")] public static T Uuid<T>(string uuid) where T : EntityObject => null;
            }

            /// Compile-time loops: foreach (int i in Unroll.Range(0, 3)) is expanded at compile time.
            public static class Unroll
            {
                [Intrinsic("unroll.range")] public static int[] Range(int from, int toExclusive) => null;
            }

            /// Execute contexts.
            public static class Exec
            {
                [Intrinsic("exec.run")] public static void Run(string subcommands, System.Action action) { }
                [Intrinsic("exec.at")] public static void At(Position pos, System.Action action) { }
            }

            public static class Builtins
            {
                [Intrinsic("asm")] public static void __asm(string commands) { }
                [Intrinsic("asmf")] public static void __asmf(string command) { }
                [Intrinsic("worldspawn")] public static Position GetWorldSpawn() => default;
                [Intrinsic("setworldspawn")] public static void SetWorldSpawn(Position pos) { }
                [Intrinsic("spawn.id")] public static void SpawnEntity(string id, Position pos, int count = 1) { }
                /// Pauses this method for one tick (or `ticks`): the rest of the method runs later via /schedule.
                /// The caller does not wait — it continues right away.
                [Intrinsic("wait")] public static void Wait(int ticks = 1) { }
            }
        }

        namespace EntityLib
        {
            public class Entity
            {
                [MCS.Intrinsic("entity.new")] public Entity(EntityType type) { }
                protected Entity() { }

                [MCS.Nbt("Health", "float")] public float Health { get; set; }
                [MCS.McAttribute("max_health")] public float maxHealth { get; set; }
                [MCS.McAttribute("max_health")] public float MaxHealth { get; set; }
                [MCS.McAttribute("movement_speed")] public float MovementSpeed { get; set; }
                [MCS.McAttribute("attack_damage")] public float AttackDamage { get; set; }
                [MCS.McAttribute("armor")] public float Armor { get; set; }
                [MCS.Nbt("Fire", "short")] public int Fire { get; set; }
                [MCS.Nbt("Air", "short")] public int Air { get; set; }
                [MCS.Nbt("NoAI", "byte")] public bool NoAI { get; set; }
                [MCS.Nbt("Silent", "byte")] public bool Silent { get; set; }
                [MCS.Nbt("Glowing", "byte")] public bool Glowing { get; set; }
                [MCS.Nbt("Invulnerable", "byte")] public bool Invulnerable { get; set; }
                [MCS.Nbt("NoGravity", "byte")] public bool NoGravity { get; set; }
                [MCS.Nbt("PersistenceRequired", "byte")] public bool PersistenceRequired { get; set; }
                [MCS.Nbt("UUID", "int[]")] public int[] uuid => default!;
                [MCS.Nbt("UUID", "int[]")] public int[] UUID => default!;

                [MCS.Intrinsic("entity.pos")] public MCS.Position Position => default;
                [MCS.Intrinsic("entity.kill")] public void Kill() { }
                [MCS.Intrinsic("entity.tp")] public void Teleport(MCS.Position pos) { }
                /// A new, unspawned entity object of the same type with the same pre-spawn properties.
                [MCS.Intrinsic("obj.clone")] public Entity Clone() => null;
                /// Discards this object: it cannot be used any more.
                [MCS.Intrinsic("obj.dispose")] public void Dispose() { }
            }
        }

        namespace DisplayLib
        {
            public enum Billboard { Fixed, Vertical, Horizontal, Center }
            public enum TextAlignment { Center, Left, Right }
            public enum ItemDisplayMode
            {
                None,
                [MCS.McId("thirdperson_lefthand")] ThirdPersonLeftHand, [MCS.McId("thirdperson_righthand")] ThirdPersonRightHand,
                [MCS.McId("firstperson_lefthand")] FirstPersonLeftHand, [MCS.McId("firstperson_righthand")] FirstPersonRightHand,
                Head, Gui, Ground, Fixed,
            }

            /// Common part of block, item and text displays (an entity: Kill, Teleport, Glowing … work too).
            public abstract class Display : EntityLib.Entity
            {
                [MCS.Nbt("billboard", "enum")] public Billboard Billboard { get; set; }
                [MCS.Nbt("view_range", "float")] public float ViewRange { get; set; }
                [MCS.Nbt("shadow_radius", "float")] public float ShadowRadius { get; set; }
                [MCS.Nbt("shadow_strength", "float")] public float ShadowStrength { get; set; }
                [MCS.Nbt("width", "float")] public float Width { get; set; }
                [MCS.Nbt("height", "float")] public float Height { get; set; }
                [MCS.Nbt("glow_color_override", "int")] public int GlowColor { get; set; }
                /// Light level 0–15 used instead of the light at the entity (block and sky light).
                [MCS.Nbt("brightness", "brightness")] public int Brightness { get; set; }
                /// Uniform scale (transformation)
                [MCS.Nbt("transformation.scale", "scale3")] public float Scale { get; set; }
                [MCS.Nbt("transformation.scale[0]", "float")] public float ScaleX { get; set; }
                [MCS.Nbt("transformation.scale[1]", "float")] public float ScaleY { get; set; }
                [MCS.Nbt("transformation.scale[2]", "float")] public float ScaleZ { get; set; }
                /// Translation of the model relative to the entity (transformation)
                [MCS.Nbt("transformation.translation[0]", "float")] public float OffsetX { get; set; }
                [MCS.Nbt("transformation.translation[1]", "float")] public float OffsetY { get; set; }
                [MCS.Nbt("transformation.translation[2]", "float")] public float OffsetZ { get; set; }
                /// Rotation of the model in degrees: around the Y axis (counterclockwise seen from above), then around the X axis
                [MCS.Nbt("transformation.left_rotation", "rot:0f,1f,0f")] public float RotationY { set { } }
                [MCS.Nbt("transformation.right_rotation", "rot:1f,0f,0f")] public float RotationX { set { } }
                /// Ticks over which changes to the transformation are animated (see Animate)
                [MCS.Nbt("interpolation_duration", "int")] public int InterpolationDuration { get; set; }
                [MCS.Nbt("start_interpolation", "int")] public int InterpolationDelay { get; set; }
                /// Ticks over which teleports are smoothed (1.20.2+)
                [MCS.Since(18, "1.20.2"), MCS.Nbt("teleport_duration", "int")] public int TeleportDuration { get; set; }
                /// Animate the transformation changes made in this tick over `ticks` ticks.
                [MCS.Intrinsic("display.animate")] public void Animate(int ticks) { }
            }

            public sealed class BlockDisplay : Display
            {
                [MCS.Intrinsic("display.new")] public BlockDisplay(BlockLib.Block block) { }
                [MCS.Intrinsic("display.new")] public BlockDisplay(string block) { }
                [MCS.Nbt("block_state", "block")] public BlockLib.Block Block { set { } }
                [MCS.Intrinsic("obj.clone")] public new BlockDisplay Clone() => null;
            }

            public sealed class ItemDisplay : Display
            {
                [MCS.Intrinsic("display.new")] public ItemDisplay(string item) { }
                [MCS.Nbt("item", "item")] public string Item { set { } }
                [MCS.Nbt("item_display", "enum")] public ItemDisplayMode Mode { get; set; }
                [MCS.Intrinsic("obj.clone")] public new ItemDisplay Clone() => null;
            }

            public sealed class TextDisplay : Display
            {
                [MCS.Intrinsic("display.new")] public TextDisplay(string text) { }
                /// Constant text, or an interpolated string with runtime values ($"Score: {x}", needs 1.20.2+)
                [MCS.Nbt("text", "text")] public string Text { set { } }
                [MCS.Nbt("line_width", "int")] public int LineWidth { get; set; }
                /// Background color as ARGB, e.g. 0x40000000 (default: translucent black)
                [MCS.Nbt("background", "int")] public int Background { get; set; }
                /// 0–255 (255 = opaque)
                [MCS.Nbt("text_opacity", "byte")] public int TextOpacity { get; set; }
                [MCS.Nbt("shadow", "byte")] public bool Shadow { get; set; }
                [MCS.Nbt("see_through", "byte")] public bool SeeThrough { get; set; }
                [MCS.Nbt("default_background", "byte")] public bool DefaultBackground { get; set; }
                [MCS.Nbt("alignment", "enum")] public TextAlignment Alignment { get; set; }
                [MCS.Intrinsic("obj.clone")] public new TextDisplay Clone() => null;
            }
        }

        namespace BlockLib
