                [MCS.Intrinsic("player.nearest")] public static Player Nearest => default!;
                [MCS.Intrinsic("player.random")] public static Player Random => default!;
                [MCS.Intrinsic("player.named")] public static Player Named(string name) => default!;
                [MCS.Intrinsic("player.tagged")] public static Player WithTag(string tag) => default!;

                [MCS.Intrinsic("player.count")] public int Count => 0;
                [MCS.Intrinsic("player.exists")] public bool Exists => false;
                [MCS.Nbt("Health", "float")] public float Health => 0;
                [MCS.Nbt("foodLevel", "int")] public int Food => 0;
                [MCS.Nbt("XpLevel", "int")] public int Level { get; set; }
                [MCS.Nbt("SelectedItemSlot", "int")] public int SelectedSlot => 0;
                [MCS.Intrinsic("player.gamemode")] public GameMode GameMode { set { } }

                [MCS.Intrinsic("player.message")] public void SendMessage(params object[] parts) { }
                [MCS.Intrinsic("player.actionbar")] public void ActionBar(params object[] parts) { }
                [MCS.Intrinsic("player.title")] public void Title(object title, object subtitle = null) { }
                [MCS.Intrinsic("player.sound")] public void PlaySound(string sound, float volume = 1, float pitch = 1) { }
                [MCS.Intrinsic("player.setspawn")] public void SetSpawn(MCS.Position pos) { }
                [MCS.Intrinsic("player.addlevels")] public void AddLevels(int levels) { }
                [MCS.Intrinsic("player.addxp")] public void AddXp(int points) { }
                [MCS.Intrinsic("player.effect")] public void Effect(string effect, int seconds, int amplifier = 0, bool hideParticles = false) { }
                [MCS.Intrinsic("player.cleareffect")] public void ClearEffect(string effect) { }
                [MCS.Intrinsic("player.cleareffects")] public void ClearEffects() { }
                [MCS.Intrinsic("player.run")] public void Run(System.Action<Player> action) { }

                // Inventory
                [MCS.Intrinsic("player.give")] public void Give(string item, int count = 1) { }
                [MCS.Intrinsic("player.clearall")] public void ClearInventory() { }
                [MCS.Intrinsic("player.clearitem")] public void ClearItem(string item, int count = -1) { }
                [MCS.Intrinsic("player.countitem")] public int CountItem(string item) => 0;
                [MCS.Intrinsic("player.hasitem")] public bool HasItem(string item) => false;
                [MCS.Intrinsic("player.setslot")] public void SetSlot(int slot, string item, int count = 1) { }
