                [MCS.Intrinsic("player.slotis")] public bool IsSlot(int slot, string item) => false;
                [MCS.Intrinsic("player.slotempty")] public bool IsSlotEmpty(int slot) => false;
                [MCS.Intrinsic("player.copyslot")] public void CopySlot(int from, int to) { }
                [MCS.Intrinsic("player.moveslot")] public void MoveSlot(int from, int to) { }
                [MCS.Intrinsic("player.swapslots")] public void SwapSlots(int a, int b) { }
            }
        }

